package compress

import (
	"bytes"
	"fmt"

	"github.com/gen2brain/avif"

	"github.com/juniorosa/go-image-optimizer/backend/internal/application/imagecompression"
	"github.com/juniorosa/go-image-optimizer/backend/internal/infrastructure/imaging"
)

func (c Compressor) compressAVIF(input []byte) (imagecompression.Result, error) {
	cfg, err := avif.DecodeConfig(bytes.NewReader(input))
	if err != nil {
		return imagecompression.Result{}, imagecompression.ErrInvalidImage
	}

	if err := imaging.ValidateDimensions(cfg, c.maxDecodedPixels()); err != nil {
		return imagecompression.Result{}, err
	}

	anim, err := avif.DecodeAll(bytes.NewReader(input), avif.Options{AutoRotate: true})
	if err != nil {
		return imagecompression.Result{}, imagecompression.ErrInvalidImage
	}
	if len(anim.Image) == 0 {
		return imagecompression.Result{}, imagecompression.ErrInvalidImage
	}

	frameCount := len(anim.Image)
	firstBounds := anim.Image[0].Bounds()
	width := firstBounds.Dx()
	height := firstBounds.Dy()

	if frameCount > 1 {
		if err := imaging.ValidateAnimatedDimensions(width, height, frameCount, c.maxAnimatedFramePixels()); err != nil {
			return imagecompression.Result{}, err
		}
	}

	options := avif.Options{
		Quality:      c.avifQuality(),
		QualityAlpha: 100,
		Speed:        6,
	}

	var output bytes.Buffer
	if frameCount > 1 {
		if err := avif.EncodeAll(&output, anim, options); err != nil {
			return imagecompression.Result{}, fmt.Errorf("encode avif animation: %w", err)
		}
	} else if err := avif.Encode(&output, anim.Image[0], options); err != nil {
		return imagecompression.Result{}, fmt.Errorf("encode avif: %w", err)
	}

	return imagecompression.Result{
		Data:        output.Bytes(),
		Format:      imagecompression.FormatAVIF,
		ContentType: "image/avif",
		Width:       width,
		Height:      height,
		Animated:    frameCount > 1,
		FrameCount:  frameCount,
	}, nil
}

package compress

import (
	"image"

	"github.com/juniorosa/go-image-optimizer/backend/internal/application/imagecompression"
	"github.com/juniorosa/go-image-optimizer/backend/internal/infrastructure/imaging"
)

const (
	// DefaultJPEGQuality keeps JPEG output visually close to the source while
	// still allowing meaningful size reduction for many camera/exported images.
	DefaultJPEGQuality = 82

	DefaultWebPQuality = 82
	DefaultAVIFQuality = 60
	DefaultHEIFQuality = 60
)

type Compressor struct {
	JPEGQuality            int
	WebPQuality            int
	AVIFQuality            int
	HEIFQuality            int
	MaxDecodedPixels       int
	MaxAnimatedFramePixels int
}

func NewCompressor() Compressor {
	return Compressor{
		JPEGQuality:            DefaultJPEGQuality,
		WebPQuality:            DefaultWebPQuality,
		AVIFQuality:            DefaultAVIFQuality,
		HEIFQuality:            DefaultHEIFQuality,
		MaxDecodedPixels:       imaging.DefaultMaxDecodedPixels,
		MaxAnimatedFramePixels: imaging.DefaultMaxAnimatedFramePixels,
	}
}

func (c Compressor) Compress(input []byte) (imagecompression.Result, error) {
	detected, err := imaging.DetectFormat(input)
	if err != nil {
		return imagecompression.Result{}, err
	}

	switch detected.Format {
	case imagecompression.FormatJPEG:
		return c.compressJPEG(input)
	case imagecompression.FormatPNG:
		return c.compressPNG(input)
	case imagecompression.FormatWebP:
		return c.compressWebP(input)
	case imagecompression.FormatAVIF:
		return c.compressAVIF(input)
	case imagecompression.FormatHEIF:
		return c.compressHEIF(input, detected.ContentType)
	case imagecompression.FormatGIF:
		return c.compressGIF(input)
	case imagecompression.FormatBMP:
		return c.compressBMP(input)
	case imagecompression.FormatTIFF:
		return c.compressTIFF(input)
	default:
		return imagecompression.Result{}, imagecompression.ErrUnsupportedFormat
	}
}

func staticResult(data []byte, format imagecompression.Format, contentType string, img image.Image) imagecompression.Result {
	bounds := img.Bounds()

	return imagecompression.Result{
		Data:        data,
		Format:      format,
		ContentType: contentType,
		Width:       bounds.Dx(),
		Height:      bounds.Dy(),
		Animated:    false,
		FrameCount:  1,
	}
}

func (c Compressor) jpegQuality() int {
	return clampQuality(c.JPEGQuality, DefaultJPEGQuality)
}

func (c Compressor) webpQuality() int {
	return clampQuality(c.WebPQuality, DefaultWebPQuality)
}

func (c Compressor) avifQuality() int {
	return clampQuality(c.AVIFQuality, DefaultAVIFQuality)
}

func (c Compressor) heifQuality() int {
	return clampQuality(c.HEIFQuality, DefaultHEIFQuality)
}

func (c Compressor) maxDecodedPixels() int {
	if c.MaxDecodedPixels <= 0 {
		return imaging.DefaultMaxDecodedPixels
	}

	return c.MaxDecodedPixels
}

func (c Compressor) maxAnimatedFramePixels() int {
	if c.MaxAnimatedFramePixels <= 0 {
		return imaging.DefaultMaxAnimatedFramePixels
	}

	return c.MaxAnimatedFramePixels
}

func clampQuality(value, fallback int) int {
	if value == 0 {
		return fallback
	}

	if value < 1 {
		return 1
	}

	if value > 100 {
		return 100
	}

	return value
}

package compress

import (
	"bytes"
	"fmt"
	"image/gif"

	"github.com/juniorosa/go-image-optimizer/backend/internal/application/imagecompression"
	"github.com/juniorosa/go-image-optimizer/backend/internal/infrastructure/imaging"
)

func (c Compressor) compressGIF(input []byte) (imagecompression.Result, error) {
	cfg, err := gif.DecodeConfig(bytes.NewReader(input))
	if err != nil {
		return imagecompression.Result{}, imagecompression.ErrInvalidImage
	}

	if err := imaging.ValidateDimensions(cfg, c.maxDecodedPixels()); err != nil {
		return imagecompression.Result{}, err
	}

	img, err := gif.DecodeAll(bytes.NewReader(input))
	if err != nil {
		return imagecompression.Result{}, imagecompression.ErrInvalidImage
	}
	if len(img.Image) == 0 {
		return imagecompression.Result{}, imagecompression.ErrInvalidImage
	}

	if len(img.Image) > 1 {
		if err := imaging.ValidateAnimatedDimensions(cfg.Width, cfg.Height, len(img.Image), c.maxAnimatedFramePixels()); err != nil {
			return imagecompression.Result{}, err
		}
	}

	var output bytes.Buffer
	if err := gif.EncodeAll(&output, img); err != nil {
		return imagecompression.Result{}, fmt.Errorf("encode gif: %w", err)
	}

	return imagecompression.Result{
		Data:        output.Bytes(),
		Format:      imagecompression.FormatGIF,
		ContentType: "image/gif",
		Width:       cfg.Width,
		Height:      cfg.Height,
		Animated:    len(img.Image) > 1,
		FrameCount:  len(img.Image),
	}, nil
}

package compress

import (
	"bytes"
	"fmt"

	"github.com/deepteams/webp"
	"github.com/deepteams/webp/animation"

	"github.com/juniorosa/go-image-optimizer/backend/internal/application/imagecompression"
	"github.com/juniorosa/go-image-optimizer/backend/internal/infrastructure/imaging"
)

func (c Compressor) compressWebP(input []byte) (imagecompression.Result, error) {
	features, err := webp.GetFeatures(bytes.NewReader(input))
	if err != nil {
		return imagecompression.Result{}, imagecompression.ErrInvalidImage
	}

	frameCount := max(1, features.FrameCount)
	if err := imaging.ValidateImageSize(features.Width, features.Height, c.maxDecodedPixels()); err != nil {
		return imagecompression.Result{}, err
	}

	if features.HasAnimation || frameCount > 1 {
		return c.compressAnimatedWebP(input, features.Width, features.Height, frameCount, features.LoopCount, features.Format == "lossless")
	}

	img, err := webp.Decode(bytes.NewReader(input))
	if err != nil {
		return imagecompression.Result{}, imagecompression.ErrInvalidImage
	}

	var output bytes.Buffer
	if err := webp.Encode(&output, img, &webp.EncoderOptions{
		Lossless:     features.Format == "lossless",
		Quality:      float32(c.webpQuality()),
		Method:       4,
		Exact:        true,
		AlphaQuality: 100,
	}); err != nil {
		return imagecompression.Result{}, fmt.Errorf("encode webp: %w", err)
	}

	return staticResult(output.Bytes(), imagecompression.FormatWebP, "image/webp", img), nil
}

func (c Compressor) compressAnimatedWebP(input []byte, width, height, frameCount, loopCount int, lossless bool) (imagecompression.Result, error) {
	if err := imaging.ValidateAnimatedDimensions(width, height, frameCount, c.maxAnimatedFramePixels()); err != nil {
		return imagecompression.Result{}, err
	}

	anim, err := animation.Decode(bytes.NewReader(input))
	if err != nil {
		return imagecompression.Result{}, imagecompression.ErrInvalidImage
	}
	if len(anim.Frames) == 0 {
		return imagecompression.Result{}, imagecompression.ErrInvalidImage
	}
	if err := anim.DecodeFrames(); err != nil {
		return imagecompression.Result{}, imagecompression.ErrInvalidImage
	}

	decoder, err := animation.NewAnimDecoder(anim)
	if err != nil {
		return imagecompression.Result{}, imagecompression.ErrInvalidImage
	}

	var output bytes.Buffer
	encoder := animation.NewEncoder(&output, width, height, &animation.EncodeOptions{
		LoopCount:       loopCount,
		BackgroundColor: anim.BackgroundColor,
		Quality:         c.webpQuality(),
		Lossless:        lossless,
	})
	if len(anim.ICC) > 0 {
		encoder.SetICCProfile(anim.ICC)
	}
	if len(anim.EXIF) > 0 {
		encoder.SetEXIF(anim.EXIF)
	}
	if len(anim.XMP) > 0 {
		encoder.SetXMP(anim.XMP)
	}

	for decoder.HasNext() {
		frame, duration, err := decoder.NextFrame()
		if err != nil {
			return imagecompression.Result{}, imagecompression.ErrInvalidImage
		}

		if err := encoder.AddFrame(frame, duration); err != nil {
			return imagecompression.Result{}, fmt.Errorf("encode webp frame: %w", err)
		}
	}

	if err := encoder.Close(); err != nil {
		return imagecompression.Result{}, fmt.Errorf("encode webp animation: %w", err)
	}

	return imagecompression.Result{
		Data:        output.Bytes(),
		Format:      imagecompression.FormatWebP,
		ContentType: "image/webp",
		Width:       width,
		Height:      height,
		Animated:    true,
		FrameCount:  frameCount,
	}, nil
}

package imaging

import (
	"image"

	"github.com/juniorosa/go-image-optimizer/backend/internal/application/imageprocessing"
)

const (
	// DefaultMaxDecodedPixels limits decoded image memory growth. A 32 MP RGBA
	// image needs roughly 128 MiB before encoder overhead.
	DefaultMaxDecodedPixels = 32_000_000

	// DefaultMaxAnimatedFramePixels caps canvas-sized animation work. The limit
	// is width * height * frame count, not bytes, so codecs can share it.
	DefaultMaxAnimatedFramePixels = 64_000_000
)

func ValidateDimensions(cfg image.Config, maxPixels int) error {
	return ValidateImageSize(cfg.Width, cfg.Height, maxPixels)
}

func ValidateImageSize(width, height, maxPixels int) error {
	if width <= 0 || height <= 0 {
		return imageprocessing.ErrInvalidImage
	}

	if width > maxPixels/height {
		return imageprocessing.ErrImageTooLarge
	}

	return nil
}

func ValidateAnimatedDimensions(width, height, frameCount, maxPixels int) error {
	if err := ValidateImageSize(width, height, DefaultMaxDecodedPixels); err != nil {
		return err
	}

	if frameCount <= 0 {
		return imageprocessing.ErrInvalidImage
	}

	if width > maxPixels/height/frameCount {
		return imageprocessing.ErrAnimationTooLarge
	}

	return nil
}

package resize

import (
	"bytes"
	"context"
	"image"
	"image/color"
	"image/color/palette"
	"image/draw"
	"image/gif"

	"github.com/deepteams/webp"
	"github.com/deepteams/webp/animation"
	"github.com/juniorosa/go-image-optimizer/backend/internal/application/imageprocessing"
	"github.com/juniorosa/go-image-optimizer/backend/internal/application/imageresize"
	"github.com/juniorosa/go-image-optimizer/backend/internal/infrastructure/imaging"
)

func decodeWebP(input []byte, detected imaging.DetectedFormat) (imageresize.Source, error) {
	f, err := webp.GetFeatures(bytes.NewReader(input))
	if err != nil {
		return nil, imageprocessing.ErrInvalidImage
	}
	if err := imaging.ValidateAnimatedDimensions(f.Width, f.Height, max(1, f.FrameCount), imageresize.MaxFramePixels); err != nil {
		return nil, err
	}
	if !f.HasAnimation && f.FrameCount <= 1 {
		img, err := webp.Decode(bytes.NewReader(input))
		if err != nil {
			return nil, imageprocessing.ErrInvalidImage
		}
		return staticSource(img, detected, f.Format == "lossless"), nil
	}
	anim, err := animation.Decode(bytes.NewReader(input))
	if err != nil || len(anim.Frames) == 0 {
		return nil, imageprocessing.ErrInvalidImage
	}
	if err := imaging.ValidateAnimatedDimensions(f.Width, f.Height, len(anim.Frames), imageresize.MaxFramePixels); err != nil {
		return nil, err
	}
	if err := anim.DecodeFrames(); err != nil {
		return nil, imageprocessing.ErrInvalidImage
	}
	return source{
		info: imageresize.Info{Width: f.Width, Height: f.Height, FrameCount: len(anim.Frames), Format: detected.Format, ContentType: detected.ContentType},
		encode: func(ctx context.Context, w, h int) ([]byte, error) {
			decoder, err := animation.NewAnimDecoder(anim)
			if err != nil {
				return nil, imageprocessing.ErrInvalidImage
			}
			var output bytes.Buffer
			encoder := animation.NewEncoder(&output, w, h, &animation.EncodeOptions{LoopCount: f.LoopCount, BackgroundColor: anim.BackgroundColor, Quality: 82, Lossless: f.Format == "lossless"})
			if len(anim.ICC) > 0 {
				encoder.SetICCProfile(anim.ICC)
			}
			for decoder.HasNext() {
				if err := ctx.Err(); err != nil {
					return nil, err
				}
				frame, duration, err := decoder.NextFrame()
				if err != nil {
					return nil, imageprocessing.ErrInvalidImage
				}
				if err := encoder.AddFrame(scaleImage(frame, w, h), duration); err != nil {
					return nil, err
				}
			}
			if err := encoder.Close(); err != nil {
				return nil, err
			}
			return output.Bytes(), nil
		},
	}, nil
}

func decodeGIF(input []byte, detected imaging.DetectedFormat) (imageresize.Source, error) {
	cfg, err := gif.DecodeConfig(bytes.NewReader(input))
	if err != nil {
		return nil, imageprocessing.ErrInvalidImage
	}
	if err := imaging.ValidateDimensions(cfg, imageresize.MaxPixels); err != nil {
		return nil, err
	}
	// Count image descriptors before DecodeAll allocates frame buffers.
	frames, err := gifFrameCount(input, cfg.Width, cfg.Height)
	if err != nil {
		return nil, err
	}
	anim, err := gif.DecodeAll(bytes.NewReader(input))
	if err != nil || len(anim.Image) != frames {
		return nil, imageprocessing.ErrInvalidImage
	}
	info := imageresize.Info{Width: cfg.Width, Height: cfg.Height, FrameCount: frames, Format: detected.Format, ContentType: detected.ContentType}
	var pixels image.Image
	if frames == 1 {
		canvas := image.NewRGBA(image.Rect(0, 0, cfg.Width, cfg.Height))
		draw.Draw(canvas, anim.Image[0].Bounds(), anim.Image[0], anim.Image[0].Bounds().Min, draw.Src)
		pixels = canvas
	}
	return source{pixels: pixels, info: info, encode: func(ctx context.Context, w, h int) ([]byte, error) {
		bounds := image.Rect(0, 0, cfg.Width, cfg.Height)
		canvas := image.NewRGBA(bounds)
		// A transparent source starts with a transparent canvas. Otherwise use
		// the logical screen background from the source global color table.
		background := color.Color(color.Transparent)
		transparent := false
		for _, c := range anim.Image[0].Palette {
			_, _, _, a := c.RGBA()
			transparent = transparent || a == 0
		}
		if !transparent {
			if global, ok := anim.Config.ColorModel.(color.Palette); ok && int(anim.BackgroundIndex) < len(global) {
				background = global[anim.BackgroundIndex]
			}
		}
		draw.Draw(canvas, bounds, image.NewUniform(background), image.Point{}, draw.Src)
		outputPalette := append(color.Palette{color.Transparent}, palette.WebSafe...)
		resized := &gif.GIF{LoopCount: anim.LoopCount, Delay: anim.Delay, Config: image.Config{Width: w, Height: h, ColorModel: outputPalette}, BackgroundIndex: 0}
		for i, frame := range anim.Image {
			if err := ctx.Err(); err != nil {
				return nil, err
			}
			disposal := byte(0)
			if i < len(anim.Disposal) {
				disposal = anim.Disposal[i]
			}
			var previous *image.RGBA
			if disposal == gif.DisposalPrevious {
				previous = image.NewRGBA(bounds)
				copy(previous.Pix, canvas.Pix)
			}
			draw.Draw(canvas, frame.Bounds(), frame, frame.Bounds().Min, draw.Over)
			scaled := scaleImage(canvas, w, h)
			quantized := image.NewPaletted(scaled.Bounds(), outputPalette)
			draw.FloydSteinberg.Draw(quantized, quantized.Bounds(), scaled, image.Point{})
			// GIF has binary transparency. Quantize color separately, then
			// restore the transparent pixels so opaque dark pixels stay opaque.
			for y := 0; y < h; y++ {
				for x := 0; x < w; x++ {
					if scaled.RGBAAt(x, y).A < 128 {
						quantized.SetColorIndex(x, y, 0)
					} else if quantized.ColorIndexAt(x, y) == 0 {
						quantized.SetColorIndex(x, y, uint8(outputPalette[1:].Index(scaled.At(x, y))+1))
					}
				}
			}
			resized.Image = append(resized.Image, quantized)
			resized.Disposal = append(resized.Disposal, gif.DisposalBackground)
			switch disposal {
			case gif.DisposalBackground:
				fill := background
				for _, c := range frame.Palette {
					_, _, _, a := c.RGBA()
					if a == 0 {
						fill = color.Transparent
						break
					}
				}
				draw.Draw(canvas, frame.Bounds(), image.NewUniform(fill), image.Point{}, draw.Src)
			case gif.DisposalPrevious:
				canvas = previous
			}
		}
		var output bytes.Buffer
		err := gif.EncodeAll(&output, resized)
		return output.Bytes(), err
	}}, nil
}

func gifFrameCount(input []byte, width, height int) (int, error) {
	if len(input) < 13 {
		return 0, imageprocessing.ErrInvalidImage
	}
	p := 13
	if input[10]&0x80 != 0 {
		p += 3 << ((input[10] & 7) + 1)
	}
	count := 0
	for p < len(input) {
		block := input[p]
		p++
		switch block {
		case 0x3b:
			if count == 0 {
				return 0, imageprocessing.ErrInvalidImage
			}
			return count, nil
		case 0x21:
			p++ // extension label; followed by data sub-blocks
		case 0x2c:
			if p+9 > len(input) {
				return 0, imageprocessing.ErrInvalidImage
			}
			packed := input[p+8]
			p += 9
			if packed&0x80 != 0 {
				p += 3 << ((packed & 7) + 1)
			}
			p++ // LZW minimum code size
			count++
			if err := imaging.ValidateAnimatedDimensions(width, height, count, imageresize.MaxFramePixels); err != nil {
				return 0, err
			}
		default:
			return 0, imageprocessing.ErrInvalidImage
		}
		for {
			if p >= len(input) {
				return 0, imageprocessing.ErrInvalidImage
			}
			size := int(input[p])
			p++
			if size == 0 {
				break
			}
			p += size
		}
	}
	return 0, imageprocessing.ErrInvalidImage
}
